const apartmentCodes=['A1','A2','A3','B1','B2','B3'];
const demo:Overview={role:'admin',email:'',my_apartments:[],apartments:apartmentCodes.map((code,i)=>({id:String(i),code,heating_share:[19.25,14,16.75,19.25,14,16.75][i],common_share:1})),expenses:[],payments:[],readings:[],fuel_deliveries:[],tank:null,tank_history:[]};
const navigation:{id:Tab;name:string;icon:string}[]=[{id:'home',name:'Αρχική',icon:'⌂'},{id:'expenses',name:'Κοινόχρηστα',icon:'▤'},{id:'heating',name:'Θέρμανση',icon:'♨'},{id:'announcements',name:'Ανακοινώσεις',icon:'🔔'},{id:'payments',name:'Πληρωμές',icon:'€'},{id:'residents',name:'Κάτοικοι',icon:'♙'},{id:'history',name:'Ιστορικό',icon:'◷'},{id:'reports',name:'Αναφορές',icon:'▥'},{id:'account',name:'Λογαριασμός',icon:'⚙'}];
const amount=(v:string)=>Math.round(Number(v.replace(',','.'))*100);
const nowMonth=()=>new Date().toISOString().slice(0,7);
const historicalElectricityNotes:Record<string,string>={
 '2026-05':'Το ποσό των 50,00 € για το κοινόχρηστο ρεύμα είναι προσωρινή εκτίμηση, επειδή ο λογαριασμός δεν είχε ακόμη εκδοθεί. Περιλήφθηκε για να μην επιβαρυνθούν οι κάτοικοι με μεγάλο ποσό στον επόμενο μήνα. Το ποσό αυτό συνυπολογίστηκε στην εκκαθάριση των επόμενων λογαριασμών ρεύματος.',
 '2026-06':'Το ποσό των 50,00 € για το κοινόχρηστο ρεύμα είναι προσωρινή εκτίμηση, επειδή ο λογαριασμός δεν είχε ακόμη εκδοθεί. Περιλήφθηκε για να αποφευχθεί μεγάλη εφάπαξ επιβάρυνση. Το ποσό αυτό συνυπολογίστηκε στην εκκαθάριση των επόμενων λογαριασμών ρεύματος.'
};
function ElectricityNotice({month}:{month:string}){const note=historicalElectricityNotes[month];return note?<div className="electricity-notice" role="note"><strong>ⓘ Ενημέρωση για το κοινόχρηστο ρεύμα</strong><p>{note}</p></div>:null;}
type PaymentState='paid'|'partial'|'unpaid'|'none';
function PaymentBadge({state}:{state:PaymentState}){const labels={paid:'Εξοφλήθηκε',partial:'Μερική πληρωμή',unpaid:'Εκκρεμεί',none:'Χωρίς χρέωση'};const symbols={paid:'✓',partial:'◐',unpaid:'!',none:'—'};return <span className={'payment-badge payment-badge--'+state} role="status"><span aria-hidden="true" className="payment-badge-icon">{symbols[state]}</span>{labels[state]}</span>;}
function paymentState(due:number,paid:number):PaymentState{return due<=0?'none':paid>=due?'paid':paid>0?'partial':'unpaid';}
type ExpenseDetail={month:string;address:string;items:Array<{name:string;amount_cents:number}>;total_cents:number;apartments:Array<{apartment_code:string;due_cents:number}>};
function ResidentMonthExpense({month,code,due,paid,balance}:{month:string;code:string;due:number;paid:number;balance:number}){
 const [detail,setDetail]=useState<ExpenseDetail|null>(null);
 const [error,setError]=useState('');
 const [loading,setLoading]=useState(false);
 const [expanded,setExpanded]=useState(false);
 const monthLabel=new Date(month+'-01T12:00:00').toLocaleDateString('el-GR',{month:'long',year:'numeric'});
 async function toggle(){const next=!expanded;setExpanded(next);if(next&&!detail&&!loading){setLoading(true);setError('');try{setDetail(await request<ExpenseDetail>('/statements/detail?month='+encodeURIComponent(month)));}catch(e){setError((e as Error).message);}finally{setLoading(false);}}}
 return <div className="resident-month resident-month-accordion"><button type="button" className="resident-month-trigger" aria-expanded={expanded} onClick={toggle}><strong>{monthLabel}</strong><strong>{money(due)}</strong><PaymentBadge state={paymentState(due,paid)}/><span className="resident-month-chevron" aria-hidden="true">{expanded?'⌃':'⌄'}</span></button>{expanded&&<div className="resident-month-content"><div className="resident-line"><span>Πληρωμή</span><span>{money(paid)}</span></div><div className="resident-line"><span>Υπόλοιπο</span><strong>{money(balance)}</strong></div><ElectricityNotice month={month}/>{loading&&<p className="muted">Φόρτωση αναλυτικών δαπανών…</p>}{error&&<p className="error" role="alert">{error}</p>}{detail&&<><h3>Ανάλυση δαπανών πολυκατοικίας</h3><div className="resident-expense-items">{detail.items.map((item,i)=><div className="resident-line" key={i}><span>{item.name}</span><strong>{money(item.amount_cents)}</strong></div>)}<div className="resident-line"><strong>Σύνολο πολυκατοικίας</strong><strong>{money(detail.total_cents)}</strong></div><div className="resident-line"><strong>Χρέωση διαμερίσματος {code}</strong><strong>{money(detail.apartments.find(a=>a.apartment_code===code)?.due_cents??due)}</strong></div></div><button type="button" onClick={()=>window.print()}>Προβολή / Αποθήκευση PDF</button><div id="common-statement" className="statement-print resident-print-statement"><h1>ΚΟΙΝΟΧΡΗΣΤΑ</h1><p>{detail.address} · {monthLabel.toUpperCase()}</p><h3>Αναλυτικές δαπάνες</h3><table><thead><tr><th>Δαπάνη</th><th>Ποσό</th></tr></thead><tbody>{detail.items.map((item,i)=><tr key={i}><td>{item.name}</td><td>{money(item.amount_cents)}</td></tr>)}<tr><th>Σύνολο πολυκατοικίας</th><th>{money(detail.total_cents)}</th></tr></tbody></table><h3>Διαμέρισμα {code}</h3><table><tbody><tr><th>Χρέωση</th><td>{money(due)}</td></tr><tr><th>Πληρωμένο</th><td>{money(paid)}</td></tr><tr><th>Υπόλοιπο</th><td>{money(balance)}</td></tr></tbody></table><ElectricityNotice month={month}/></div></>}</div>}</div>;
}
